// Generates js/core/keybindings/ribbon-commands.generated.js (#714): every
// built-in ribbon button with a fixed id, so it can get a keyboard shortcut.
// Only the tab that is open is mounted, so the list cannot come from the DOM;
// it comes from the tab sources. ribbon-commands.test.mjs checks that the
// generated file is up to date.
//
// Usage (from open-pdf-studio/): node scripts/genereer-lint-sneltoetsen.mjs

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const hier = path.dirname(fileURLToPath(import.meta.url));
const app = path.resolve(hier, '..');
const LINT = path.join(app, 'js/solid/components/ribbon');
export const DOEL = path.join(app, 'js/core/keybindings/ribbon-commands.generated.js');

/** Tab source -> ribbon tab id, in the order the ribbon shows them. */
export const TABBLADEN = [
  ['HomeTab.jsx', 'home'],
  ['ViewTab.jsx', 'view'],
  ['DrawingTab.jsx', 'drawing'],
  ['CommentTab.jsx', 'comment'],
  ['OrganizeTab.jsx', 'organize'],
  ['ArrangeTab.jsx', 'arrange'],
  ['HelpTab.jsx', 'help'],
];

/** The text of the tag from `start` up to its closing '>' (braces and strings skipped). */
function tagTekst(src, start) {
  let diepte = 0;
  let quote = null;
  for (let i = start; i < src.length; i++) {
    const c = src[i];
    if (quote) {
      if (c === '\\') { i++; continue; }
      if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === '`') { quote = c; continue; }
    if (c === '{') diepte++;
    else if (c === '}') diepte--;
    else if (c === '>' && diepte === 0) return src.slice(start, i + 1);
  }
  return src.slice(start);
}

/** t-function name -> namespace, from `const { t } = useTranslation('ribbon')` and `{ t: tMenu }`. */
function vertaalFuncties(src) {
  const uit = {};
  for (const m of src.matchAll(/const\s*\{\s*t(?:\s*:\s*(\w+))?\s*\}\s*=\s*useTranslation\(\s*'(\w+)'\s*\)/g)) {
    uit[m[1] || 't'] = m[2];
  }
  return uit;
}

function tekstVan(attr, tag, functies) {
  const re = new RegExp(`\\b${attr}=(?:"([^"]*)"|\\{([\\s\\S]*?)\\}(?=\\s+[\\w-]+=|\\s*/?>))`);
  const m = tag.match(re);
  if (!m) return null;
  if (m[1] !== undefined) return m[1].trim() ? { label: m[1].trim() } : null;
  const expr = m[2];
  const sleutel = expr.match(/\b(t\w*)\(\s*'([^']+)'/);
  if (sleutel && functies[sleutel[1]]) {
    const fallback = expr.match(/\|\|\s*'([^']+)'/)?.[1];
    return { labelKey: `${functies[sleutel[1]]}:${sleutel[2]}`, ...(fallback ? { label: fallback } : {}) };
  }
  const literal = expr.match(/^\s*'([^']+)'\s*$/);
  return literal ? { label: literal[1] } : null;
}

/** All ribbon buttons with a fixed id in the given sources: [{ id, tab, labelKey?, label? }]. */
export function lintOpdrachtenUit(bronnen) {
  const uit = [];
  const gezien = new Set();
  for (const { bron, tab } of bronnen) {
    const functies = vertaalFuncties(bron);
    for (const m of bron.matchAll(/<RibbonButton\b/g)) {
      const tag = tagTekst(bron, m.index);
      const id = tag.match(/\bid="([^"]+)"/)?.[1];
      if (!id || gezien.has(id)) continue;
      const tekst = tekstVan('label', tag, functies) || tekstVan('title', tag, functies);
      if (!tekst) continue;
      gezien.add(id);
      uit.push({ id, tab, ...tekst });
    }
  }
  return uit;
}

export function leesBronnen() {
  return TABBLADEN.map(([bestand, tab]) => ({ tab, bron: fs.readFileSync(path.join(LINT, bestand), 'utf8') }));
}

export function genereer(lijst = lintOpdrachtenUit(leesBronnen())) {
  const regels = lijst.map((o) => `  ${JSON.stringify(o)},`).join('\n');
  return `// GENERATED by scripts/genereer-lint-sneltoetsen.mjs — do not edit by hand.\n`
    + `// Every built-in ribbon button with a fixed id (#714); ribbon-commands.test.mjs\n`
    + `// fails when a tab changes and this file was not regenerated.\n\n`
    + `export const RIBBON_COMMANDS = Object.freeze([\n${regels}\n]);\n`;
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  fs.writeFileSync(DOEL, genereer());
  console.log(`${path.relative(app, DOEL)} geschreven`);
}
